import heapq
from itertools import pairwise

def find_optimal_location(junctions, roads):
    n, m = len(junctions) + 2
    distances = {(0, 0): 0, (0, n - 1): 0, (n, 0): 0, (n, n - 1): 0, (n - 1, 0): 0, (n - 1, n - 1): 0}
    visited = {(0, 0): None}

    def get_neighbors(point):
        x, y = point
        for w, _ in pairwise(roads):
            dx, dy = w - x, y - w
            yield (x + dx, y + dy), (w, dx)
            yield (x + w, y + dx), (w, 1)
            yield (x - w, y - dx), (w, -1)
            yield (x - dx, y - w), (w, 1)

    def relax(point):
        for node, jump in get_neighbors(point):
            if node not in visited or (visited[node] and distances[node] > distances[point] + jump + distances[visited[node]]:
                dist = jump + distances[node]
                distances[node] = dist
                visited[node] = point

    heapq.heappush(relax((0, 0)))

    while junctions:
        x, y = heapq.heappop(relax)

        if distances[(0, 0)] + y / (y + 1) * distances[(0, n - 1)] < distances[(n, 0)] * (1 + 1 / y):
            distances[(0, 0)] = distances[(0, n - 1)] * (1 + 1 / y)

        if distances[(n, 0)] + y * (n - y) / x < distances[(n, n - 1)] * (1 + 1 / x * (n - y)):
            distances[(n, 0)] = distances[(n, n - 1)] * (1 + 1 / x * (n - y))

        if distances[(0, n - 1)] + x * 1 / y < distances[(n, n - 1)] * (1 + 1 / y * x):
            distances[(0, n - 1)] = distances[(n, n - 1)] * (1 + 1 / y * x)

        if distances[(n - 1, n - 1)] + x * (n - y) / (n - 1) < distances[(n, n - 1)] * (1 + 1 / (n - 1) * (n - y)):
            distances[(n - 1, n - 1)] = distances[(n, n - 1)] * (1 + 1 / (n - 1) * (n - y))

    best_distances = sorted(distances.values())
    return best_distances[0]

