from collections import defaultdict, deque
import sys
from fractions import Fraction

def build_graph(n, k, a):
    graph = defaultdict(list)
    for i in range(n):
        if a[i] != -1:
            z = min(a[i], k - 1 - a[i]) * min(a[i], k - 1 - a[i])
            graph[len(a)].append((i, z))
    return graph

def bfs(mid, G, mod):
    bonds = deque([sorted((u, 1) for u, _ in G[mid])])
    seen = defaultdict(int)
    total_bonds = 0
    while bonds:
        cur_valid = sorted(bonds.popleft())
        while cur_valid and (pre := cur_valid[-1][0]) <= mid:
            seen[cur_valid.pop()], total_bonds += 1
        seen[mid] = total_bonds
        cur_valid.pop()
        next_valid = set()
        for u in cur_valid:
            for v in G[u]:
                if (w, auto) := v:
                    new_w, new_auto = max(
                        (w := max(w, (u - v) * min(u, k - 1 - u) / 2) + auto),
                        (w := max(w, (u - v) * min(v, k - 1 - v) / 2) + auto)
                    )
                    seen[(u, auto)], next_valid |= seen[u]
                    if w >= mid:
                        yield w, rest, w % mod

def answer(n, k, a):
    pref_sum = [Fraction(0, 1)]
    k_3mul = [Fraction(0, 1)]
    for _a in (-1, 0, 1):
        next_pre = defaultdict(int)
        next_k_3mul = defaultdict(int)
        for u, in_u in bfs(_a, build_graph(n, k, a), 10**9 + 7):
            next_pre[k_3mul[u] * 3] += in_u
        for u in next_pre:
            if next_k_3mul[u] < next_pre[u]:
                next_k_3mul[u] = next_pre[u]
            else:
                next_k_3mul[u] += next_pre[u]
        pref_sum.append(next_pre.copy())
        k_3mul += next_k_3mul
    return pref_sum[k - 1]

