import sys
from typing import List, Tuple, Set, Dict

def build_tree(n: int, edges: List[Tuple[int, int]]) -> Dict[int, Set[int]]:
    # Build adjacency list representation
    tree: Dict[int, Set[int]] = {i: set() for i in range(1, n+1)}
    for u, v in edges:
        tree[u].add(v)
        tree[v].add(u)
    return tree

def is_link_in_path(tree: Dict[int, Set[int]], node_a: int, node_b: int) -> bool:
    stack = [node_a]
    visited = set()
    while stack:
        current = stack.pop()
        if current == node_b:
            return True
        visited.add(current)
        stack.extend(tree[current] - visited)
    return False

def find_root(tree: Dict[int, Set[int]]) -> int:
    root = None
    for node in tree:
        if is_link_in_path(tree, node, 1):
            if root is None:
                root = node
            else:
                raise Exception("Multiple roots")
    return root

def find_link_in_set(edges: List[Tuple[int, int]], node: int, set_id: int) -> Tuple[int, int]:
    for edge in edges:
        u, v = edge
        if node != u and node == v:
            return min(u, v)
        elif node == u and node != v and (u, v) in set(set_id):
            return u
        elif node != u and node == v and (v, u) in set(set_id):
            return node

def can_link(node_a: int, node_b: int, edges_set: Set[int], edges_set_link: Set[Tuple[int, int]]) -> bool:
    u_a, v_a = find_link_in_set(edges_set, node_a, 0)
    u_b, v_b = find_link_in_set(edges_set, node_b, 0)

    if u_a == v_b:
        return u_b == node_a
    if u_b == v_a:
        return u_a == node_b

    for edge in edges_set_link:
        if u_a == edge[0] and v_b == edge[1]:
            return True
        elif u_b == edge[0] and v_a == edge[1]:
            return True

    return False

def find_max_matching(tree: Dict[int, Set[int]], edges_set: Set[Tuple[int, int]]) -> int:
    set_edge_number = len(edges_set)
    visited = set()
    while visited:
        for node in tree:
            if node == 1:
                break
            if node not in visited:
                visited.add(node)
                if can_link(*find_link_in_set(edges_set, node, 1), edges_set, set(edges_set)):
                    edges_set.add((node, 1))
    return set_edge_number - len(edges_set)

def restore(n: int, edges1: List[Tuple[int, int]], edges2: List[Tuple[int, int]]) -> List[Tuple[int]]: 
    tree = build_tree(n, edges1)
    root = find_root(tree)
    edges_set = set(edges1)
    edges_set.add((root, root))
    # Exclude the link between root and itself
    edges_set.remove((root, root))

    for i in range(1, n+1):
        if i == root:
            continue
        u = root
        while u != i:
            edges_set.add((i, u))
            u = u % i

    edges_link = mapi(node, edge, (node, next(range(node))) for node, edges in tree.items() for edge in edges)
    to_be_restored = []
    for i in range(1, n+1):
        for edge in edges2:
            if can_link(*edge, edges_link, set(edges2)):
                edges_set.add(edge)
                to_be_restored.append((i, edge))

    max_match = find_max_matching(tree, edges_set)
    return max_match, list(sorted(to_be_restored, key=lambda x: edges1[x[0]][1]))

