        dp['R'] = dp['C'] = [0] * R
        dp['R'][0], dp['C'][0] = 1, 1

        right, down = [0] * (R + 1), [0] * (C + 1)

        for c in range(1, C):
            right[0], right[c] = down[0], down[c]

        for r in range(1, R):
            for c in range(1, C):
                right[c], down[c] = dp['R'][c], dp['C'][c]

            for r in range(-C, R):
                for c in range(-R, 0):
                    if grid[r + R][c + C] != string[r + 1 + R * c + C]:
                        break
                    if r + R < R and c + C < C:
                        dp['R'][r + 1] += down[c + 1]
                    dp['C'][c + 1] += right[r + 1]

            for r in range(-R, R + 1):
                for c in range(1, C):
                    dp['C'][c] -= dp['R'][c]
                    dp['R'][c] += dp['C'][c]

        return sum(dp['R']) + sum(dp['C'])

