    def within(ins_x_1, ins_y_1, ins_x_2, ins_y_2, x, y): 
        return not ((x < min(ins_x_1, ins_x_2) or x >= max(ins_x_1, ins_x_2))  
                    or (y < min(ins_y_1, ins_y_2) or y >= max(ins_y_1, ins_y_2)))

    areas = [0, 0, 0, 0]
    for idx in [1, 3]:  # loop to check for 1st and 4th direction
        ins_x_1, ins_y_1, ins_x_2, ins_y_2 = x + len, y, x, y + len
        areas[idx] += within(ins_x_1, ins_y_1, ins_x_2, ins_y_2, x, y)
    for idx in [2, 4]:  # loop to check for 2nd and 3rd direction
        ins_x_1, ins_y_1, ins_x_2, ins_y_2 = x, y, x - len, y
        areas[idx] += within(ins_x_1, ins_y_1, ins_x_2, ins_y_2, x, y)
