import itertools
import re
from collections import defaultdict

def is_modest(num):
    num_str = str(num)
    for i in range(len(num_str)):
        if (num_str[i] == "0" and i > 0) or int(num_str[:i+1]) % 3 == 0:
            return False
    return True

def pattern_count(s):
    count = defaultdict(int)
    pattern = re.compile(r'^(10+|0)+$')
    for i in range(len(s)):
        if pattern.match(s[i:]):
            count[s[i:]] += 1
    return count

def find_max_substrings(l, r, n):
    max_count = 0
    for i in range(n):
        for j in range(n):
            if l <= i+j <= r:
                length = i+j
                if is_modest(''.join(map(str, range(l, l+i+j+1)))):
                    max_count = max(max_count, length)
    return max_count

def find_smallest_string(l, r, n):
    for i in range(n):
        for j in range(n):
            sub = str(i) + '1' * j
            if is_modest(sub) and len(sub) > 1:
                return sub

def solve(l, r, n):
    count = find_max_substrings(l, r, n)
    string = find_smallest_string(l, r, n)
    max_count = find_max_substrings(int(string), int(string), int(n))
    string = find_smallest_string(l, r, max_count+2)
    return f"{count}\n{string[2:]}"

