def solve(n: int, p: int, M: int, m: int, x: int, y: int, l: int, r: int, u: int, v: int) -> int:
    if u == v or l < r:
        return -1  # If stations interfere or lowest freq is greater than highest freq
    return l - 1  # Return signal power

def main(n: int, p: int, M: int, m: int, complaints: List[int], stations: List[int], constraints: List[int], pairs: List[int]) -> List[int]:
    pairs = sorted(zip(pairs, constraints))  # Sort pairs by station index, then by constraints
    num_contracts = 0
    f = 1
    stations_used = [0] * p  # Array to check for stations that can fulfill conditions

    for _, (u, v) in pairs:
        while f <= M and transient(u, v):
            if stations_used[u] or stations_used[v]:
                f += 1
            else:
                num_contracts += 1
                stations_used[u] = stations_used[v] = f
                break

    if num_contracts < n:
        return -1  # If not enough contracts can be fulfilled

    result = list(range(1, 1 + p))  # Default set of stations
    for u, v in pairs:
        result[u:u+1] = [u] + result[u+1:]
        result[v: v + 1] = [v] + result[v + 1:]

    for i in set(result):  # Remove unused stations
        if not any(result.count(i) > 1):
            items = []
            for item in result:
                if i in item:
                    items.append(item)
            if all(solve(n, p, M, m, x, y, l, r, u, v) == constrain for item in items for x, y, l, r, u, v, constrain in constraints):
                result = items
                break

    return result

