class DSU:
    def __init__(self, N):
        self.parents = range(N)
        self.ranks = [0] * N

    def union(self, i, j):
        iRoot, jRoot = self.find(i), self.find(j)
        if iRoot == jRoot:
            return False
        if self.ranks[iRoot] < self.ranks[jRoot]:
            iRoot, jRoot = jRoot, iRoot
        self.ranks[iRoot] += self.ranks[jRoot]
        self.parents[jRoot] = iRoot
        return True

