def shortest_manhattan_distance(edges):
    crossings = []
    for start, end, length in edges:
        crossings.append((start-1, start-1 + length))
        crossings.append((end-2, end-2))
    crossings.sort()

    left, right = 0, max(x for _, x in crossings)
    best_distance, best_crossing = 0, None

    while left < right:
        mid = (left + right) // 2
        if check(left, mid, crossings):
            right = mid
            best_distance = mid
            best_crossing = mid
        else:
            left = mid + 1

    return best_distance

# Helper function to check if placing the restaurant at mid gives a valid solution
def check(start, mid, crossings):
    if start + mid > crossings[-1][1]:
        return True

    for i in range(len(crossings)):
