from collections import deque

mod = 1000000007
def mul(divisor, multiplier):
    return ((divisor * multiplier) % mod)

def mod_inverse(divisor):
    return pow(divisor, mod - 2, mod)

class State:
    def __init__(self, number):
        self.number = number
        self.previous_operations = []
        self.length = 0

class TuringMachine:
    def generate_state_data(self, number):
        steps = []
        current_number = number
        for i in range(30):
            if current_number & (1 << i) == 0:
                steps.append("ff")
            else:
                steps.append("1")
                current_number = (current_number - 1) & number
        steps.append("1")
        state = State(number)
        state.previous_operations = steps
        state.length = len(steps)
        return state

# get number of different sequences
def get_number_sequences(number):
    sequences = 0
    state = TuringMachine().generate_state_data(number)
    while state.length != 0:
        sequences = (sequences + mul(state.length, pow(state.number ** state.length, pow(mod, -1))))
        state.length -= 1
    sequences = mul(sequences, pow(2, state.length-1))
    return sequences

# get minimum length of the sequences
def get_min_length(number):
    if number == 0:
        return 1
    number_high = number
    executed_operations = deque()
    while number_high > 0:
        if number_high & 1:
            if executed_operations != deque():
                executed_operations.pop()
            if executed_operations[-1] == "f":
                executed_operations.pop()
                executed_operations.append("f")
            elif executed_operations[-1] == "1":
                executed_operations.pop()
                executed_operations.append("0")
        else:
            executed_operations.append("0")
        number_high >>= 1
    return 1 + (((len(executed_operations) + 2) // 3) + ((len(executed_operations) + 2) % 3))

# solution
def solution(x):
    largest = max(32, len(bin(x))-2)
    mapped_x = (2 ** (largest - 1)) - 1

    sequences = get_number_sequences(mapped_x)
    minimum_length = get_min_length(mapped_x)

    with open("seq", "w") as f:
        f.write(str(sequences) + "\n" + str(minimum_length))
    return sequences % mod, minimum_length % mod  

