def length_to_power_of_two(n):
    power = 0
    while n > 0:
        n = n & (n - 1)
        power += 1
    return 31 - power

def catalan_number(n):
    if n == 0:
        return 1
    c = 1
    for i in range(1, n + 1):
        c *= (2 * i - 1)
        c //= i
    return c % 1000000007

def solution(x):
    n = int(x, 2)
    length = length_to_power_of_two(n)
    catalan = catalan_number(length)
    return toString(catalan, length), toString(6, 6)

def toString(x, length):
    return str(x) + '*' + '*' * (length - 2) + str(x) + '*' * (length - 2)

