import sys

def count_ways(l, r, p):
    def max_value(max_val, operator, n, ops):
        if n <= max_val:
            return True
        for value in range(n // 2, max_val + 1):
            max_val = min(max_val, value * (1 if operator == '*' else max_val) + value)
            ops += 1 if value % 2 == 0 else 0
            if ops > p:
                break
            if value > 1 and max_value(max_val, operator, value, ops) and max_value(max_val, operator, value - 1, ops):
                return True
        return False

    max_val = 1 if p > 0 else 0
    first_val, second_val = 1, 0
    for i in range(1, p + 1):
        number = second_val * first_val
        first_val, second_val = number, number % 2
        is_possible = max_value(max_val, '*', i, 0)
        if not is_possible and sys.maxsize % number == 0:
            max_val = number
    return r - max_val + 1 if l <= 0 else r - max_val + 1 + (l != 1)

