from heapq import heappop, heappush
from typing import List

def dijkstra(graph: List[List[int]], source: int) -> List[int]:
    n = len(graph)
    dist = [float('inf')] * n
    visited = [False] * n
    dist[source] = 0
    pq = []
    heappush(pq, (0, source))

    while pq:
        d, u = heappop(pq)
        if visited[u]:
            continue
        visited[u] = True
        for v in graph[u]:
            if dist[u] + 1 < dist[v]:
