import itertools

class GridTransformation:
    def __init__(self, grid, strings):
        self.grid = grid
        self.strings = strings

    def transform_string(self, s):
        def transform_char(char):
            return chr(ord('A') + grid.index(char))
        return ''.join(transform_char(c) for c in s)

    def count_occurrences(self, string, start_r, start_c):
        count = 0
        for row, col in itertools.product(range(start_r, len(self.grid) + start_r, 1), range(start_c, len(self.grid[0]) + start_c, 1)):
            if self.grid[row][col] == self.strings[0] and self.grid[row][col - 1] == string[0] and self.grid[row + 1][col - 1] == string[-1]:
                count += 1
        return count

def count_transformed_strings(transformed_grid, strings):
    grid = transformed_grid
    ans = [0] * (len(strings) + 1)
    for index, s in enumerate(strings):
        transformed_s = transform_string(s)
        ans[index + 1] = ans[index] + grid.count(transformed_s)
    return ans

def solve_case(r, c, q, grid):
    strings = []
    for _ in range(q):
        string = " ".join(input().strip().split())
        transformed_string = transform_string(string)
        string_i = strings.index(string) if string in strings else len(strings)
        strings.append(transformed_string)
        print(f'Service request for string "{string}" yields {grid.count(transformed_string)}, expecting {ans[string_i + 1]}.')

